css:
#tongsci1-3-1-1-3-balance .t-hist { grid-template-columns: 620px minmax(0, 1fr); }
.wp-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #000; touch-action: none; cursor: ew-resize; user-select: none; }
.wp-stage img.wp-new, .wp-stage img.wp-old { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; pointer-events: none; -webkit-user-drag: none; }
.wp-stage[data-pair="0"] { background: #0b2a5e; }
.wp-cut { position: absolute; top: 0; bottom: 0; width: 44px; margin-left: -22px; cursor: ew-resize; outline: none; }
.wp-cut::before { content: ""; position: absolute; left: 20px; top: 0; bottom: 0; width: 4px; background: #ffd84d; box-shadow: 0 0 10px rgba(0,0,0,.6); }
.wp-cut i { position: absolute; left: 0; top: 50%; width: 44px; height: 44px; margin-top: -22px; border-radius: 50%; background: #ffd84d; box-shadow: 0 3px 10px rgba(0,0,0,.5); }
.wp-cut i::before { content: "◀ ▶"; position: absolute; inset: 0; display: grid; place-items: center; font-size: 13px; font-weight: 800; color: #1d2433; letter-spacing: -1px; }
.wp-cut:focus-visible i { outline: 4px solid var(--hl); outline-offset: 2px; }
.wp-tag { position: absolute; top: 60px; padding: 4px 12px; border-radius: 8px; background: rgba(10,16,32,.78); color: #fff; font-weight: 800; font-size: 20px; pointer-events: none; }
.wp-tl { left: 12px; } .wp-tr { right: 12px; }
.wp-key { position: absolute; left: 12px; bottom: 12px; margin: 0; padding: 4px 10px; border-radius: 8px; background: rgba(10,16,32,.78); color: #fff; font-size: 16px; display: flex; align-items: center; gap: 6px; pointer-events: none; }
.wp-key i { display: inline-block; width: 46px; height: 12px; border-radius: 6px; background: linear-gradient(90deg, #7a3cc8, #2a3fd6, #24b8d8); }
.wp-key i + i, .wp-key i:last-of-type { background: linear-gradient(90deg, #3cc84a, #e8d23a, #e0452c); }
.wp-key[hidden] { display: none; }
.wp-tray { align-items: center; }
.wp-thumbs { display: flex; gap: 10px; }
.wp-thumbs button { display: flex; align-items: center; gap: 8px; padding: 4px 12px 4px 4px; border: 2px solid var(--rule); border-radius: 10px; background: #fff; font: inherit; font-size: 18px; font-weight: 700; cursor: pointer; }
.wp-thumbs button[aria-pressed="true"] { border-color: var(--accent); background: #fffbe6; }
.wp-thumbs img { width: 52px; height: 40px; object-fit: cover; border-radius: 6px; }
.wp-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; }
.wp-q { margin: 0; padding-left: 1.4em; font-size: 18px; line-height: 1.45; }

